Object.assign(window.TEM8_DICTIONARY, {"outweigh":{"oxford":{"phon":"ˌaʊtˈweɪ","pos":"verb","senses":[{"en":"to be greater or more important than something","cn":"重于；大于；超过","ex":{"en":"The advantages far outweigh the disadvantages.","cn":"利远大于弊。"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"（在重要性、益处、意义等上）重于，大于，超过","en":"If one thing outweighs another, the first thing is of greater importance, benefit, or significance than the second thing.","ex":{"en":"The medical benefits of x-rays far outweigh the risk of having them","cn":"X光在医学上的益处远甚于它带来的风险。"}}]},"media":{"uk":"media/uk/outweigh__gb_1.mp3","us":"media/us/outweigh__us_1.mp3"},"examples":[{"en":"The advantages far outweigh the disadvantages.","cn":"利远大于弊。"},{"en":"The benefits of the scheme outweigh the disadvantages.","cn":"这项计划利大于弊。"}]},"outdoor":{"media":{"uk":"media/uk/outdoor__gb_1.mp3","us":"media/us/outdoor__us_1.mp3"},"oxford":{"phon":"ˈaʊtdɔː(r)","pos":"adjective","senses":[{"en":"used, happening or located outside rather than in a building","cn":"户外的；室外的","ex":{"en":"outdoor pursuits/recreation/activities","cn":"户外消遣／休闲／活动"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"户外的；室外的；野外的","en":"Outdoor activities or things happen or are used outside and not in a building.","ex":{"en":"If you enjoy outdoor activities, this is the trip for you","cn":"如果你喜欢户外运动，这一旅行很适合你。"}}]},"examples":[{"en":"I'm not really the outdoor type (= I prefer indoor activities).","cn":"我不太喜爱户外活动。"},{"en":"outdoor clothing/activities","cn":"户外穿的衣服/活动"}]},"outfitter":{"media":{"uk":"media/uk/outfitter__gb_1.mp3","us":"media/us/outfitter__us_1.mp3"},"oxford":{"phon":"ˈaʊtfɪtə(r)","pos":"noun","senses":[{"en":"a shop that sells men’s clothes or school uniforms","cn":"（出售男装或校服的）服装店","lab":"old-fashioned, British English，，"},{"en":"a shop that sells equipment for camping and other outdoor activities","cn":"户外用品店；露营装备店","lab":"North American English"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（专门的）服装商店，装备商店","en":"also outfitters. An outfitter or an outfitters is a shop that sells clothes and equipment for a specific purpose.","ex":{"en":"...J. Hepworth, the men's outfitter.","cn":"赫普沃思男装店"}}]}},"ourselves":{"media":{"uk":"media/uk/ourselves__gb_1.mp3","us":"media/us/ourselves__us_1.mp3"},"oxford":{"phon":"ɑːˈselvz","pos":"pronoun","senses":[{"en":"the reflexive form of we; used when you and another person or other people together cause and are affected by an action","cn":"（we 的反身形式）我们自己","ex":{"en":"We shouldn't blame ourselves for what happened.","cn":"我们不应该为发生的事责怪自己。"}},{"en":"used to emphasize we or us; sometimes used instead of these words","cn":"（用于强调或代替 we 或 us）我们自己，亲自","ex":{"en":"We've often thought of going there ourselves.","cn":"我们常想亲自到那里去一趟。"}}]},"collins":{"senses":[{"pos":"PRON-REFL 反身代词","cn":"我们自己","en":"You use ourselves to refer to yourself and one or more other people as a group.","ex":{"en":"We sat round the fire to keep ourselves warm","cn":"我们围坐在火边取暖。"}},{"pos":"PRON-REFL 反身代词","cn":"（泛指）我们自己，人们自己（当主语和宾语为同一群人时，用作动词或介词的宾语）","en":"A speaker or writer sometimes uses ourselves to refer to people in general. Ourselves is used as the object of a verb or preposition when the subject refers to the same people.","ex":{"en":"We all know that when we exert ourselves our heart rate increases.","cn":"我们都知道太卖命了会导致心跳加速。"}},{"pos":"PRON-REFL-EMPH 强调反身代词","cn":"（用于强调第一人称复数主语；在比较正式的英语中，有时代替 us 作动词或介词的宾语以示强调）我们自己，我们本人","en":"You use ourselves to emphasize a first person plural subject. In more formal English, ourselves is sometimes used instead of 'us' as the object of a verb or preposition, for emphasis.","ex":{"en":"Others are feeling just the way we ourselves would feel in the same situation","cn":"别人此时的感受和我们自己在同样的情形下时没什么两样。"}},{"pos":"PRON-REFL-EMPH 强调反身代词","cn":"我们自己;我们亲自","en":"If you say something such as 'We did it ourselves', you are indicating that something was done by you and a particular group of other people, rather than anyone else.","ex":{"en":"We villagers built that ourselves, we had no help from anyone.","cn":"那是我们村民自己修建的，没有依靠任何人的帮助。"}}]},"examples":[{"en":"We shouldn't blame ourselves for what happened.","cn":"我们不应该为发生的事责怪自己。"},{"en":"We had the pool all to ourselves.","cn":"这个游泳池完全供我们自己使用。"}]},"outdoors":{"media":{"uk":"media/uk/outdoors__gb_1.mp3","us":"media/us/outdoors__us_1.mp3"},"oxford":{"phon":"ˌaʊtˈdɔːz","pos":"adverb","senses":[{"en":"outside, rather than in a building","cn":"在户外；在野外","ex":{"en":"The rain prevented them from eating outdoors.","cn":"雨天使他们无法户外用餐。"}},{"en":"the countryside, away from buildings and busy places","cn":"野外；旷野；郊外","lab":"especially North American English","ex":{"en":"They both have a love of the outdoors.","cn":"他们俩都喜爱郊外的环境。"},"pos":"noun"}]},"collins":{"senses":[{"pos":"ADV 副词","cn":"在户外；在室外；在野外","en":"If something happens outdoors, it happens outside in the fresh air rather than in a building.","ex":{"en":"It was warm enough to be outdoors all afternoon","cn":"天气很暖和，整个下午都可以呆在户外。"}},{"pos":"N-SING 单数名词","cn":"户外工作；野外活动；户外休闲","en":"You refer to the outdoors when talking about work or leisure activities which take place outside away from buildings.","ex":{"en":"I'm a lover of the outdoors","cn":"我喜爱户外运动。"}}]},"examples":[{"en":"Come to Canada and enjoy the great outdoors.","cn":"到加拿大来享受蓝天碧野吧！"},{"en":"They both have a love of the outdoors.","cn":"他们俩都喜爱郊外的环境。"}]},"outpost":{"media":{"uk":"media/uk/outpost__gb_1.mp3","us":"media/us/outpost__us_1.mp3"},"oxford":{"phon":"ˈaʊtpəʊst","pos":"noun","senses":[{"en":"a small military camp away from the main army, used for watching an enemy’s movements, etc.","cn":"前哨（基地）"},{"en":"a small town or group of buildings in a lonely part of a country","cn":"偏远村镇；孤零住区","ex":{"en":"a remote outpost","cn":"偏远的村镇"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"贸易站；前哨基地；（设在国外的）军事基地","en":"An outpost is a small group of buildings used for trading or military purposes, either in a distant part of your own country or in a foreign country.","ex":{"en":"...a remote mountain outpost, linked to the outside world by the poorest of roads.","cn":"靠一条崎岖艰险的山路与外界相连的偏远山区哨站"}}]},"examples":[{"en":"the last outpost of civilization","cn":"文明的边缘地区"},{"en":"a remote outpost","cn":"偏远的村镇"}]},"outstrip":{"media":{"uk":"media/uk/outstrip__gb_1.mp3","us":"media/us/outstrip__us_1.mp3"},"oxford":{"phon":"ˌaʊtˈstrɪp","pos":"verb","senses":[{"en":"to become larger, more important, etc. than somebody/something","cn":"比…大（或重要等）；超过；胜过","ex":{"en":"Demand is outstripping supply.","cn":"需求快超过供给了。"}},{"en":"to be faster, better or more successful than somebody you are competing against","cn":"超过，超越（竞争对手）","ex":{"en":"Their latest computer outstrips all its rivals.","cn":"他们最新型的计算机超越了所有的对手。"}},{"en":"to run faster than somebody in a race so that you pass them","cn":"比…跑得快；超越","ex":{"en":"She soon outstripped the slower runners.","cn":"她很快超过了跑得慢的选手。"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"超过；胜过","en":"If one thing outstrips another, the first thing becomes larger in amount, or more successful or important, than the second thing.","ex":{"en":"In the mid-eighteenth century the production of food far outstripped the rise in population","cn":"18世纪中叶食物的产量远远超过人口的增长。"}}]},"examples":[{"en":"Their latest computer outstrips all its rivals.","cn":"他们最新型的计算机超越了所有的对手。"},{"en":"Demand is outstripping supply.","cn":"需求快超过供应了。"}]},"outright":{"media":{"uk":"media/uk/outright__gb_1.mp3","us":"media/us/outright__us_1.mp3"},"oxford":{"phon":"ˈaʊtraɪt","pos":"adjective","senses":[{"en":"complete and total","cn":"完全的；彻底的；绝对的","ex":{"en":"an outright ban/rejection/victory","cn":"完全禁止；断然拒绝；彻底胜利"}},{"en":"open and direct","cn":"公开的；直率的；直截了当的","ex":{"en":"There was outright opposition to the plan.","cn":"该计划遭到公开直接反对。"}},{"en":"in a direct way and without trying to hide anything","cn":"公开地；直率地；毫无保留地","ex":{"en":"Why don't you ask him outright if it's true?","cn":"你为什么不直截了当地问他那是否属实？"},"pos":"adverb"},{"en":"clearly and completely","cn":"完全彻底；干净利落","ex":{"en":"Neither candidate won outright.","cn":"两个候选人谁也没干脆利落地获胜。"},"pos":"adverb"},{"en":"not gradually; immediately","cn":"一下子；骤然间；立即","ex":{"en":"Most of the crash victims were killed outright.","cn":"飞机坠毁的遇难者大都是当场死亡。"},"pos":"adverb"}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"直率的；公开的；直截了当的","en":"You use outright to describe behaviour and actions that are open and direct, rather than indirect.","ex":{"en":"Kawaguchi finally resorted to an outright lie.","cn":"川口最后干脆睁着眼睛说瞎话。"}},{"pos":"ADJ 形容词","cn":"完全的；彻底的；全部的","en":"Outright means complete and total.","ex":{"en":"She had failed to win an outright victory","cn":"她没能大获全胜。"}}]},"examples":[{"en":"We had saved enough money to buy the house outright.","cn":"我们存了足够的钱，能一次付清款项买下这所房子。"},{"en":"Why don't you ask him outright if it's true?","cn":"你为什么不直截了当地问他那是否属实？"}]},"outstanding":{"media":{"uk":"media/uk/outstanding__gb_1.mp3","us":"media/us/outstanding__us_1.mp3"},"oxford":{"phon":"aʊtˈstændɪŋ","pos":"adjective","senses":[{"en":"extremely good; excellent","cn":"优秀的；杰出的；出色的","ex":{"en":"an outstanding player/achievement/success","cn":"杰出的运动员／成绩／成就"}},{"en":"not yet paid, done, solved, etc.","cn":"未支付的；未完成的；未解决的","ex":{"en":"She has outstanding debts of over £500.","cn":"她未清偿的债务超过 500 英镑。"}},{"en":"very obvious or important","cn":"突出的；明显的；重要的","g":"[usually before noun]","ex":{"en":"the outstanding features of the landscape","cn":"这一景观的突出特征"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"杰出的；出众的；优秀的","en":"If you describe someone or something as outstanding, you think that they are very remarkable and impressive.","ex":{"en":"Derartu is an outstanding athlete and deserved to win.","cn":"德拉尔图是位优秀的运动员，赢得比赛也是理所当然。"}},{"pos":"ADJ 形容词","cn":"（款项）未支付的，未结清的","en":"Money that is outstanding has not yet been paid and is still owed to someone.","ex":{"en":"The total debt outstanding is $70 billion","cn":"未偿债务总额达700亿美元。"}},{"pos":"ADJ 形容词","cn":"未解决的；未完成的","en":"Outstanding issues or problems have not yet been resolved.","ex":{"en":"We still have some outstanding issues to resolve before we'll have a treaty that is ready to sign.","cn":"我们签协议之前还有一些未尽事宜待解决。"}},{"pos":"ADJ 形容词","cn":"重要的；显著的；突出的","en":"Outstanding means very important or obvious.","ex":{"en":"The company is an outstanding example of a small business that grew into a big one","cn":"该公司是小企业成长为大企业的突出例子。"}}]},"examples":[{"en":"She has outstanding debts of over £500.","cn":"她未清偿的债务超过 500 英镑。"},{"en":"an area of outstanding natural beauty","cn":"自然风景极美的地区"}]},"outer":{"oxford":{"phon":"ˈaʊtə(r)","pos":"adjective","senses":[{"en":"on the outside of something","cn":"外表的；外边的","ex":{"en":"the outer layers of the skin","cn":"皮肤表层"}},{"en":"furthest from the inside or centre of something","cn":"远离中心的；外围的","lab":"figurative","ex":{"en":"I walked along the outer edge of the track.","cn":"我沿着跑道的外缘走。"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"外面的；外部的；远离中心的","en":"The outer parts of something are the parts which contain or enclose the other parts, and which are furthest from the centre.","ex":{"en":"He heard a voice in the outer room.","cn":"他听到外屋有人说话。"}}]},"media":{"uk":"media/uk/outer__gb_1.mp3","us":"media/us/outer__us_1.mp3"},"examples":[{"en":"I walked along the outer edge of the track.","cn":"我沿着跑道的外缘走。"},{"en":"( figurative ) to explore the outer (= most extreme) limits of human experience","cn":"探索人类经验的极限"}]},"outline":{"media":{"uk":"media/uk/outline__gb_1.mp3","us":"media/us/outline__us_1.mp3"},"oxford":{"phon":"ˈaʊtlaɪn","pos":"verb","senses":[{"en":"to give a description of the main facts or points involved in something","cn":"概述；略述","ex":{"en":"He outlined his plan to leave St. Petersburg.","cn":"他简单讲述了他离开圣彼得堡的计划。"}},{"en":"to show or mark the outer edge of something","cn":"显示…的轮廓；勾勒…的外形","g":"[usually passive]","ex":{"en":"They saw the huge building outlined against the sky.","cn":"他们看见了在天空的映衬下那座巨大建筑的轮廓。"}},{"en":"a description of the main facts or points involved in something","cn":"概述；梗概","ex":{"en":"This is a brief outline of the events.","cn":"这就是事件的简要情况。"},"pos":"noun"},{"en":"the line that goes around the edge of something, showing its main shape but not the details","cn":"轮廓线；略图","ex":{"en":"At last we could see the dim outline of an island.","cn":"我们终于能看到一座小岛朦胧的轮廓了。"},"pos":"noun"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"概述；概括","en":"If you outline an idea or a plan, you explain it in a general way.","ex":{"en":"The mayor outlined his plan to clean up the town's image","cn":"市长概述了他整顿市容的计划。"}},{"pos":"N-COUNT 可数名词","cn":"概要；梗概","en":"An outline is a general explanation or description of something.","ex":{"en":"Following is an outline of the survey findings","cn":"以下是调查结果概要。"}},{"pos":"V-PASSIVE 被动动词","cn":"（因背后的光线）显示…的轮廓（或外形）","en":"You say that an object is outlined when you can see its general shape because there is light behind it.","ex":{"en":"The Ritz was outlined against the lights up there","cn":"高悬的灯光映照出里兹饭店的轮廓。"}},{"pos":"N-COUNT 可数名词","cn":"（尤指模糊的）轮廓，外形","en":"The outline of something is its general shape, especially when it cannot be clearly seen.","ex":{"en":"He could see only the hazy outline of the goalposts.","cn":"他只能看见球门柱模糊的轮廓。"}}]},"examples":[{"en":"They saw the huge building outlined against the sky.","cn":"他们看见了在天空的映衬下那座巨大建筑的轮廓。"},{"en":"We outlined our proposals to the committee.","cn":"我们向委员会提纲挈领地讲了讲我们的提案。"}]},"outset":{"media":{"uk":"media/uk/outset__gb_1.mp3","us":"media/us/outset__us_1.mp3"},"oxford":{"phon":"ˈaʊtset","pos":"noun","senses":[{"en":"at/from the beginning of sth","cn":"从开始"}]},"collins":{"senses":[{"pos":"PHRASE 短语","cn":"在开始时/ 从一开始","en":"If something happens at the outset of an event, process, or period of time, it happens at the beginning of it. If something happens from the outset it happens from the beginning and continues to happen.","ex":{"en":"Decide at the outset what kind of learning programme you want to follow","cn":"开始时就选定自己的学习方案。"}}]},"examples":[{"en":"I made it clear right from the outset that I disapproved.","cn":"从一开始我就明确地说我不赞成。"},{"en":"It was clear from the outset that there were going to be problems.","cn":"从一开始就很清楚会有问题出现的。"}]},"our":{"media":{"uk":"media/uk/our__gb_1.mp3","us":"media/us/our__us_1.mp3"},"oxford":{"phon":"ɑː(r)","pos":"determiner","senses":[{"en":"belonging to us; connected with us","cn":"我们的","ex":{"en":"our daughter/dog/house","cn":"我们的女儿／狗／房子"}},{"en":"used to refer to or address God or a holy person","cn":"（用于称上帝或圣人）","ex":{"en":"Our Father (= God)","cn":"上帝"}}]},"collins":{"senses":[{"pos":"DET-POSS 所有格限定词","cn":"我们的","en":"You use our to indicate that something belongs or relates both to yourself and to one or more other people.","ex":{"en":"We're expecting our first baby","cn":"我们怀上了第一个孩子。"}},{"pos":"DET-POSS 所有格限定词","cn":"（泛指）我们的，人们的","en":"A speaker or writer sometimes uses our to indicate that something belongs or relates to people in general.","ex":{"en":"The quality of our life depends on keeping well","cn":"我们的生活质量取决于健康状况。"}},{"pos":"DET-POSS 所有格限定词","cn":"（与家庭成员的姓名连用）我家的","en":"Speakers sometimes use our with the name of a member of their family.","ex":{"en":"Our Barry had a habit of doing that sort of thing.","cn":"我家巴里就习惯干那种事。"}}]},"examples":[{"en":"We showed them some of our photos.","cn":"我们给他们看了我们的一些照片。"},{"en":"And now, over to our Rome correspondent …","cn":"现在是驻罗马记者的报道 …"}]},"outfit":{"media":{"uk":"media/uk/outfit__gb_1.mp3","us":"media/us/outfit__us_1.mp3"},"oxford":{"phon":"ˈaʊtfɪt","pos":"noun","senses":[{"en":"a set of clothes that you wear together, especially for a particular occasion or purpose","cn":"全套服装，装束（尤指为某场合或目的）","g":"[countable]","ex":{"en":"She was wearing an expensive new outfit.","cn":"她穿着一身昂贵的新衣裳。"}},{"en":"a group of people working together as an organization, business, team, etc.","cn":"团队；小组；分队","g":"[countable + singular or plural verb]","lab":"informal","ex":{"en":"a market research outfit","cn":"市场调查组"}},{"en":"a set of equipment that you need for a particular purpose","cn":"全套装备；成套工具","g":"[countable]","ex":{"en":"a bicycle repair outfit","cn":"修自行车的整套工具"}},{"en":"to provide somebody/something with equipment or clothes for a special purpose","cn":"装备；配置设备；供给服装","ex":{"en":"The ship was outfitted with a 12-bed hospital.","cn":"这艘船配备了一所有 12 个床位的医院。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"全套服装","en":"An outfit is a set of clothes.","ex":{"en":"She was wearing an outfit she'd bought the previous day","cn":"她穿着前一天买的那套衣服。"}},{"pos":"N-COUNT 可数名词","cn":"机构;组织","en":"You can refer to an organization as an outfit .","ex":{"en":"He works for a private security outfit","cn":"他在一家私人保安公司工作。"}},{"pos":"VERB 动词","cn":"装备；配备；供给","en":"To outfit someone or something means to provide them with equipment for a particular purpose.","ex":{"en":"They outfitted him with artificial legs","cn":"他们为他安了假腿。"}}]},"examples":[{"en":"The ship was outfitted with a 12-bed hospital.","cn":"这艘船上配置了一个有 12 个床位的医疗室。"},{"en":"This was the fourth album by the top rock outfit.","cn":"这是这个顶级摇滚乐队的第四张唱片专辑。"}]},"outlying":{"media":{"uk":"media/uk/outlying__gb_1.mp3","us":"media/us/outlying__us_1.mp3"},"oxford":{"phon":"ˈaʊtlaɪɪŋ","pos":"adjective","senses":[{"en":"far away from the cities of a country or from the main part of a place","cn":"边远的；偏远的；远离市镇的","ex":{"en":"outlying areas","cn":"偏远地区"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"偏僻的；边远的；远离城市的","en":"Outlying places are far away from the main cities of a country.","ex":{"en":"Tourists can visit outlying areas like the Napa Valley Wine Country","cn":"游客可以前往像纳帕谷酒乡这样远离城市喧嚣的地方游览。"}}]},"examples":[{"en":"outlying areas","cn":"偏远地区"},{"en":"one of the outlying suburbs","cn":"边远郊区之一"}]},"outcome":{"media":{"uk":"media/uk/outcome__gb_1.mp3","us":"media/us/outcome__us_1.mp3"},"oxford":{"phon":"ˈaʊtkʌm","pos":"noun","senses":[{"en":"the result or effect of an action or event","cn":"结果；效果","lab":"formal","ex":{"en":"The likely outcome is a compromise.","cn":"结果可能是妥协。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"结果；结局；后果","en":"The outcome of an activity, process, or situation is the situation that exists at the end of it.","ex":{"en":"Mr. Singh said he was pleased with the outcome","cn":"辛格先生说他对这一结果感到满意。"}}]},"examples":[{"en":"These costs are payable whatever the outcome of the case.","cn":"无论讼案结果如何，这些费用都应照付。"},{"en":"We are waiting to hear the final outcome of the negotiations.","cn":"我们在等待谈判的最终结果。"}]},"outcry":{"media":{"uk":"media/uk/outcry__gb_1.mp3","us":"media/us/outcry__us_1.mp3"},"oxford":{"phon":"ˈaʊtkraɪ","pos":"noun","senses":[{"en":"a reaction of anger or strong protest shown by people in public","cn":"呐喊；怒吼；强烈的抗议","ex":{"en":"an outcry over the proposed change","cn":"对拟议的改革所发出的强烈抗议"}}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"强烈的抗议（或反对）","en":"An outcry is a reaction of strong disapproval and anger shown by the public or media about a recent event.","ex":{"en":"The killing caused an international outcry","cn":"这起谋杀引起了国际社会的强烈抗议。"}}]},"examples":[{"en":"an outcry over the proposed change","cn":"对拟议的改革所发出的强烈抗议"},{"en":"The new tax provoked a public outcry.","cn":"新税项引起了公众的强烈抗议。"}]},"out":{"media":{"uk":"media/uk/out__gb_1.mp3","us":"media/us/out__us_1.mp3"},"oxford":{"phon":"aʊt","pos":"adverb, preposition","senses":[{"en":"away from the inside of a place or thing","cn":"（从…里）出来","lab":"informal","ex":{"en":"She ran out into the corridor.","cn":"她跑出来，冲进走廊。"}},{"en":"away from or not at home or their place of work","cn":"不在家；不在工作地点；外出","ex":{"en":"I called Liz but she was out.","cn":"我打电话给利兹，但她不在家。"}},{"en":"outside; not in a building","cn":"在外面；在户外","ex":{"en":"It's cold out.","cn":"外面很冷。"}},{"en":"used to show that something/somebody is removed from a place, job, etc.","cn":"除掉；清除","ex":{"en":"This detergent is good for getting stains out.","cn":"这种洗涤剂能清除斑渍。"}},{"en":"away from the edge of a place","cn":"出去；离开（某地）边缘","ex":{"en":"The boy dashed out into the road.","cn":"男孩子向路中间冲去。"}},{"en":"used to show where something comes from","cn":"从；来自","ex":{"en":"He drank his beer out of the bottle.","cn":"他从瓶口直接喝啤酒。"}},{"en":"used to show what something is made from","cn":"用…制作","ex":{"en":"a statue made out of bronze","cn":"一尊青铜像"}},{"en":"used to show that somebody/something does not have any of something","cn":"没有；缺少","ex":{"en":"We're out of milk.","cn":"我们没有牛奶了。"}},{"en":"used to show that somebody/something is not or no longer in a particular state or condition","cn":"（表示不在原状态）脱离，离开","ex":{"en":"Try and stay out of trouble.","cn":"尽量别惹麻烦。"}},{"en":"used to show that somebody is no longer involved in something","cn":"（表示不再参与某事）脱离","ex":{"en":"It was an awful job and I'm glad to be out of it.","cn":"那件差事简直是受罪，我很高兴摆脱掉了。"}},{"en":"from a particular number or set","cn":"从（某个数目或集）中","ex":{"en":"You scored six out of ten.","cn":"总分十分你得了六分。"}},{"en":"clearly and loudly so that people can hear","cn":"大声地","ex":{"en":"to call/cry/shout out","cn":"大声叫／哭／喊"}},{"en":"a long or a particular distance away from a place or from land","cn":"远离（某地或陆地）；离（某地或陆地）","ex":{"en":"She's working out in Australia.","cn":"她远在澳大利亚工作。"}},{"en":"available to everyone; known to everyone","cn":"公开；发行","ex":{"en":"When does her new book come out?","cn":"她的新书什么时候出版？"}},{"en":"used to show the reason why something is done","cn":"（表示原因）因为，出于","ex":{"en":"I asked out of curiosity.","cn":"我因为好奇问了问。"}},{"en":"not in the library; borrowed by somebody else","cn":"不在图书馆；已借出","ex":{"en":"The book you wanted is out on loan.","cn":"你要的那本书借出去了。"}},{"en":"at or towards its lowest point on land","cn":"在退潮期；退潮","ex":{"en":"I like walking on the wet sand when the tide is out.","cn":"我喜欢退潮后走在湿润的沙滩上。"}},{"en":"if the sun, moon or stars are or come out, they can be seen from the earth and are not hidden by clouds","cn":"（日、月、星辰）出现，未被云遮住"},{"en":"fully open","cn":"开放","ex":{"en":"There should be some snowdrops out by now.","cn":"现在应该有雪花莲开放了。"}},{"en":"if a team or team member is out, it is no longer their turn with the bat","cn":"出局","ex":{"en":"The West Indies were all out for 364 (= after scoring 364 runs in cricket).","cn":"西印度群岛队以 364 分全队出局。"}},{"en":"if a player is out, they can no longer take part in the game","cn":"（玩家）出局","ex":{"en":"If you have no more cards, you are out. The winner is the one with the most cards.","cn":"没牌即出局。牌最多的为赢家。"}},{"en":"if the ball is out, it landed outside the line","cn":"出界","ex":{"en":"The umpire said the ball was out.","cn":"裁判员判球出界。"}},{"en":"not correct or exact; wrong","cn":"错误；不准确","ex":{"en":"I was slightly out in my calculations.","cn":"我的计算出了点小错。"}},{"en":"not possible or not allowed","cn":"不可能；不允许","ex":{"en":"Swimming is out until the weather gets warmer.","cn":"天气转暖前，游泳是不可能的。"}},{"en":"not fashionable","cn":"过时","ex":{"en":"Black is out this year.","cn":"今年黑色不时兴了。"}},{"en":"not or no longer burning or lit","cn":"熄灭","ex":{"en":"Suddenly all the lights went out.","cn":"突然间所有的灯光都灭了。"}},{"en":"at an end","cn":"结束","ex":{"en":"It was summer and school was out.","cn":"夏天，学校放假了。"}},{"en":"unconscious","cn":"无知觉；昏迷","ex":{"en":"He was out for more than an hour and came round in the hospital.","cn":"他昏迷了一个多小时，在医院才苏醒过来。"}},{"en":"on strike","cn":"罢工","lab":"British English, informal，，","ex":{"en":"The dockers stayed out for several months.","cn":"码头工人罢工了数月。"}},{"en":"to the end; completely","cn":"到底；完全地","ex":{"en":"Hear me out before you say anything.","cn":"你听我说完再讲话。"}},{"en":"a way of avoiding having to do something","cn":"回避的方法；托辞；出路","ex":{"en":"She was desperately looking for an out.","cn":"她在拼命找一条脱身之计。"},"pos":"noun"},{"en":"having told other people that you are gay or lesbian","cn":"已公开同性恋身份的；出柜的","ex":{"en":"an out gay man","cn":"已公开同性恋身份的男子"},"pos":"adjective"},{"en":"to say publicly that somebody is gay or lesbian, especially when they would prefer to keep this information private","cn":"揭露，公布（同性恋者）","ex":{"en":"He is the latest politician to be outed by the media.","cn":"他是最新一位被媒体揭露的政客。"},"pos":"verb"},{"en":"to say something publicly about somebody/something that they would prefer to keep secret","cn":"揭露，公布（别人想要保守的秘密）","ex":{"en":"The man who claimed to have found the diaries has been outed as a fraud.","cn":"声称找到日记的人被揭露是个骗子。"},"pos":"verb"},{"en":"greater, better, further, longer, etc.","cn":"超越；超过","ex":{"en":"outnumber","cn":"在数量上压倒"},"pos":"prefix"},{"en":"outside; outward; away from","cn":"在外面；向外；离开","ex":{"en":"outbuildings","cn":"附属建筑物"},"pos":"prefix"}]},"collins":{"senses":[{"pos":"ADV 副词","cn":"（拿）出；（取）出","en":"When something is in a particular place and you take it out, you remove it from that place.","ex":{"en":"Carefully pull out the centre pages","cn":"小心翼翼地抽出中间的几页。"}},{"pos":"ADV 副词","cn":"在外；在室外","en":"You can use out to indicate that you are talking about the situation outside, rather than inside buildings.","ex":{"en":"It's hot out — very hot, very humid.","cn":"外面很热——非常炎热而且非常潮湿。"}},{"pos":"ADV 副词","cn":"不在家；不在工作地点","en":"If you are out, you are not at home or not at your usual place of work.","ex":{"en":"I tried to get in touch with you yesterday evening, but I think you were out","cn":"我昨晚想要和你联系，但好像你不在家里。"}},{"pos":"ADV 副词","cn":"在他处；（通常指）在远处","en":"If you say that someone is out in a particular place, you mean that they are in a different place, usually one far away.","ex":{"en":"The police tell me they've finished their investigations out there","cn":"警方告诉我他们已完成了在那儿的调查工作。"}},{"pos":"ADV 副词","cn":"（海水或潮水）离岸","en":"When the sea or tide goes out, the sea moves away from the shore.","ex":{"en":"The tide was out and they walked among the rock pools.","cn":"潮水已经退去，他们走过岩石区的潮水潭。"}},{"pos":"ADV 副词","cn":"缺少，不足，损失（某一数量的钱）","en":"If you are out a particular amount of money, you have that amount less than you should or than you did.","ex":{"en":"Me and my friends are out ten thousand dollars, with nothing to show for it!","cn":"我和朋友亏了1万美金，还一无所得！"}},{"pos":"ADJ 形容词","cn":"（灯、火）熄灭的","en":"If a light or fire is out or goes out, it is no longer shining or burning.","ex":{"en":"All the lights were out in the house","cn":"屋里的灯全都灭了。"}},{"pos":"ADJ 形容词","cn":"（花）盛开的，吐蕊的","en":"If flowers are out, their petals have opened.","ex":{"en":"Well, the daffodils are out in the gardens and they're always a beautiful show.","cn":"哎呀，花园里的黄水仙开了，它们永远都是一道亮丽的风景。"}},{"pos":"ADJ 形容词","cn":"面世；问世；发行","en":"If something such as a book or CD is out, it is available for people to buy.","ex":{"en":"...cover versions of 40 British Number Ones — out now.","cn":"40首英国头榜歌曲的翻唱版现在上市"}},{"pos":"ADJ 形容词","cn":"罢工的","en":"If workers are out, they are on strike.","ex":{"en":"We've been out for two and a half months and we're not going back until we get what we're asking for.","cn":"我们已经罢工两个半月了，除非要求得到满足，否则我们不会复工。"}},{"pos":"ADJ 形容词","cn":"无法参赛的；淘汰的","en":"In a game or sport, if someone is out, they can no longer take part either because they are unable to or because they have been defeated."},{"pos":"ADJ 形容词","cn":"（棒球比赛中选手）出局的","en":"In baseball, a player is out if they do not reach a base safely. When three players in a team are out in an inning, then the team is out."},{"pos":"ADJ 形容词","cn":"（提议或建议）不能接受的，不值得考虑的","en":"If you say that a proposal or suggestion is out, you mean that it is unacceptable.","ex":{"en":"That's right out, I'm afraid.","cn":"那恐怕根本行不通。"}},{"pos":"ADJ 形容词","cn":"不时髦的；不流行的；过时的","en":"If you say that a particular thing is out, you mean that it is no longer fashionable at the present time.","ex":{"en":"Romance is making a comeback. Reality is out.","cn":"浪漫主义正重新流行起来，而现实主义过时了。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（计算或测量）不准确的，错误的","en":"If you say that a calculation or measurement is out, you mean that it is incorrect.","ex":{"en":"When the two ends of the tunnel met in the middle they were only a few inches out.","cn":"隧道两端在中间相接时，仅有几英寸的误差。"}},{"pos":"ADJ 形容词","cn":"打算的；试图的","en":"If someone is out to do something, they intend to do it.","ex":{"en":"Most companies these days are just out to make a quick profit.","cn":"如今，大多数公司只想能迅速获利。"}},{"pos":"VERB 动词","cn":"公开揭露（公众人物、名人等）的同性恋身份","en":"If a group of people out a public figure or famous person, they reveal that person's homosexuality against their wishes.","ex":{"en":"The New York gay action group 'Queer Nation' recently outed an American Congressman.","cn":"纽约的同性恋行动组织“酷儿国度”最近揭露一位美国国会议员为同性恋。"}},{"pos":"PREP-PHRASE 短语介词","cn":"从（某处）离开","en":"If you go out of a place, you leave it.","ex":{"en":"She let him out of the house.","cn":"她让他出了屋子。"}},{"pos":"PREP-PHRASE 短语介词","cn":"从…里面（拿、取）出来","en":"If you take something out of the container or place where it has been, you remove it so that it is no longer there.","ex":{"en":"I always took my key out of my bag and put it in my pocket.","cn":"我总是将钥匙从包里取出来放进口袋。"}},{"pos":"PREP-PHRASE 短语介词","cn":"向（窗）外","en":"If you look or shout out of a window, you look or shout away from the room where you are towards the outside.","ex":{"en":"He went on staring out of the window","cn":"他继续凝视着窗外。"}},{"pos":"PREP-PHRASE 短语介词","cn":"避开，未暴露于（太阳、雨或风）","en":"If you are out of the sun, the rain, or the wind, you are sheltered from it.","ex":{"en":"People can keep out of the sun to avoid skin cancer.","cn":"人们可以通过避免阳光照射来预防皮肤癌。"}},{"pos":"PREP-PHRASE 短语介词","cn":"摆脱，脱离（尤指令人不快的事）","en":"If someone or something gets out of a situation, especially an unpleasant one, they are then no longer in it. If they keep out of it, they do not start being in it.","ex":{"en":"In the past army troops have relied heavily on air support to get them out of trouble","cn":"过去，陆军部队在很大程度上依赖空中支援来摆脱困境。"}},{"pos":"PREP-PHRASE 短语介词","cn":"离开（机构）","en":"You can use out of to say that someone leaves an institution.","ex":{"en":"You come out of university and find there are no jobs available","cn":"从大学毕业后却找不到工作。"}},{"pos":"PREP-PHRASE 短语介词","cn":"在…之外；超过…界限","en":"If you are out of range of something, you are beyond the limits of that range.","ex":{"en":"Shaun was in the bedroom, out of earshot, watching television","cn":"肖恩在卧室里看电视，听不见。"}},{"pos":"PREP-PHRASE 短语介词","cn":"出于；由于","en":"You use out of to say what feeling or reason causes someone to do something. For example, if you do something out of pity, you do it because you pity someone.","ex":{"en":"He took up office out of a sense of duty","cn":"他就任公职是出于一种责任感。"}},{"pos":"PREP-PHRASE 短语介词","cn":"（通常指在对方不情愿的情况下）从（某人）身上（获得信息或工作成果）","en":"If you get something such as information or work out of someone, you manage to make them give it to you, usually when they are unwilling to give it.","ex":{"en":"'Where is she being held prisoner?' I asked. 'Did you get it out of him?'","cn":"“她被囚禁在什么地方？”我问道，“你从他口里套出来没有？”"}},{"pos":"PREP-PHRASE 短语介词","cn":"由…（引起）；从…中（得到）","en":"If you get pleasure or an advantage out of something, you get it as a result of being involved with that thing or making use of it.","ex":{"en":"We all had a lot of fun out of him","cn":"他给我们带来很多快乐。"}},{"pos":"PREP-PHRASE 短语介词","cn":"缺乏；没有","en":"If you are out of something, you no longer have any of it.","ex":{"en":"I can't find the sugar — and we're out of milk.","cn":"我找不到糖——而且我们也没牛奶了。"}},{"pos":"PREP-PHRASE 短语介词","cn":"用…（制成）；由…（建成）","en":"If something is made out of a particular material, it consists of that material because it has been formed or constructed from it.","ex":{"en":"Would you advise people to make a building out of wood or stone?","cn":"你会建议人们用木材还是石头建房子呢？"}},{"pos":"PREP-PHRASE 短语介词","cn":"（表示比例）每…中","en":"You use out of to indicate what proportion of a group of things something is true of. For example, if something is true of one out of five things, it is true of one fifth of all things of that kind.","ex":{"en":"Two out of five thought the business would be sold privately on their retirement or death","cn":"五个人之中有两个认为公司会在他们退休或去世时被私下卖掉。"}}]},"examples":[{"en":"He is the latest politician to be outed by gay activists.","cn":"他是被同性恋维权人士新近揭露的同性恋政治人物。"},{"en":"We've only just moved here so we feel a little out of it.","cn":"我们刚搬到这里，所以心里觉得有点不适应。"}]},"ounce":{"media":{"uk":"media/uk/ounce__gb_1.mp3","us":"media/us/ounce__us_1.mp3"},"oxford":{"phon":"aʊns","pos":"noun","senses":[{"en":"a unit for measuring weight, 116 of a pound, equal to 28.35 grams","cn":"盎司（重量单位，¹⁄₁₆ 磅，等于 28.35 克）","g":"[countable]"},{"en":"a very small quantity of something","cn":"少许；少量；一点点；丝毫","g":"[singular]","lab":"informal","ex":{"en":"There's not an ounce of truth in her story.","cn":"她所说的一点儿都不真实。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"盎司（英国和美国的重量单位，1磅合16盎司，1盎司等于28.35克）","en":"An ounce is a unit of weight used in Britain and the USA. There are sixteen ounces in a pound and one ounce is equal to 28.35 grams.","ex":{"en":"...four ounces of sugar.","cn":"4盎司糖"}},{"pos":"N-SING 单数名词","cn":"少许；少量；一点点","en":"You can refer to a very small amount of something, such as a quality or characteristic, as an ounce .","ex":{"en":"If only my father had possessed an ounce of business sense","cn":"要是我父亲有一点点经商的头脑就好了。"}}]},"examples":[{"en":"There's not an ounce of truth in her story.","cn":"她所说的一点都不真实。"},{"en":"If you had an ounce of sense you wouldn’t believe him!","cn":"你要是有一点头脑就不会相信他！"}]},"outwards":{"media":{"uk":"media/uk/outwards__gb_1.mp3","us":"media/us/outwards__us_1.mp3"},"oxford":{"phon":"ˈaʊtwədz","pos":"adverb","senses":[{"en":"towards the outside; away from the centre or from a particular point","cn":"向外；朝外","ex":{"en":"The door opens outwards.","cn":"这个门向外开。"}}]},"collins":{"senses":[{"pos":"ADV 副词","cn":"向外;朝外","en":"If something moves or faces outwards, it moves or faces away from the place you are in or the place you are talking about.","ex":{"en":"The top door opened outwards","cn":"顶上的门朝外开。"}},{"pos":"ADV 副词","cn":"（注意力）向外地，对外地","en":"If you say that a person or a group of people, such as a government, looks outwards, you mean that they turn their attention to another group that they are interested in or would like greater involvement with.","ex":{"en":"Other poor countries looked outward, strengthening their ties to the economic superpowers","cn":"其他贫穷国家将目光投向国外，加强与经济强国的联系。"}}]},"examples":[{"en":"Factories were spreading outwards from the old heart of the town.","cn":"工厂从旧城中心逐渐向外扩展。"},{"en":"The door opens outwards.","cn":"这个门向外开。"}]},"outlook":{"oxford":{"phon":"ˈaʊtlʊk","pos":"noun","senses":[{"en":"the attitude to life and the world of a particular person, group or culture","cn":"观点；见解；世界观；人生观","ex":{"en":"Travel broadens your outlook.","cn":"旅行可以开阔眼界。"}},{"en":"the likely future for somebody/something; what is likely to happen","cn":"前景；可能性","ex":{"en":"the country’s economic outlook","cn":"国家的经济前景"}},{"en":"a view from a particular place","cn":"景色；景致；景观","lab":"formal","ex":{"en":"The house has a pleasant outlook over the valley.","cn":"房子俯瞰山谷，景色宜人。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"世界观；人生观；（对生活的）观点，看法","en":"Your outlook is your general attitude towards life.","ex":{"en":"The illness had a profound effect on his outlook","cn":"这场病对他的人生观产生了深刻的影响。"}},{"pos":"N-SING 单数名词","cn":"展望；前景；可能性","en":"The outlook for something is what people think will happen in relation to it.","ex":{"en":"The economic outlook is one of rising unemployment","cn":"展望未来的经济，失业率将会上升。"}}]},"media":{"uk":"media/uk/outlook__gb_1.mp3","us":"media/us/outlook__us_1.mp3"},"examples":[{"en":"Most Western societies are liberal in outlook.","cn":"西方社会大多思想观念开放。"},{"en":"The house has a pleasant outlook over the valley.","cn":"房子俯瞰山谷，景色宜人。"}]},"ours":{"media":{"uk":"media/uk/ours__gb_1.mp3","us":"media/us/ours__us_1.mp3"},"oxford":{"phon":"ɑːz","pos":"pronoun","senses":[{"en":"the one or ones that belong to us","cn":"我们的","ex":{"en":"Their house is very similar to ours, but ours is bigger.","cn":"他们的房子和我们的十分相像，但我们的要大些。"}},{"en":"our home","cn":"我们的住处","lab":"British English, informal，，","ex":{"en":"Do you fancy coming to ours for Sunday dinner?","cn":"周日来我们家吃晚饭怎么样？"}}]},"collins":{"senses":[{"pos":"PRON-POSS 所有格代词","cn":"我们的","en":"You use ours to refer to something that belongs or relates both to yourself and to one or more other people.","ex":{"en":"Japanese democracy is certainly different from ours","cn":"日本的民主制度无疑与我们的不同。"}}]},"examples":[{"en":"Their house is very similar to ours, but ours is bigger.","cn":"他们的房子和我们的十分相像，但我们的要大些。"},{"en":"No, those are Ellie's kids. Ours are upstairs.","cn":"不，那些是埃利的孩子。我们的都在楼上。"}]},"outweighs":{"lemma":"outweigh"},"output":{"oxford":{"phon":"ˈaʊtpʊt","pos":"noun","senses":[{"en":"the amount of something that a person, a machine or an organization produces","cn":"（人、机器、机构的）产量，输出量","ex":{"en":"Manufacturing output has increased by 8 per cent.","cn":"制造业产量增长了 8%。"}},{"en":"the information, results, etc. produced by a computer","cn":"输出","lab":"computing","ex":{"en":"data output","cn":"数据输出"}},{"en":"the power, energy, etc. produced by a piece of equipment","cn":"输出功率；输出量","ex":{"en":"an output of 100 watts","cn":"输出功率 100 瓦"}},{"en":"a place where energy, power, information, etc. leaves a system","cn":"输出端","ex":{"en":"Connect a cable to the output.","cn":"把缆线接到输出端上。"}},{"en":"to supply or produce information, results, etc.","cn":"输出","ex":{"en":"Computers can now output data much more quickly.","cn":"现在计算机能更快地输出数据。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"产量；输出量；排出量","en":"Output is used to refer to the amount of something that a person or thing produces.","ex":{"en":"Manual workers need a good breakfast for high-energy output","cn":"体力劳动者身体消耗巨大，早餐要丰盛一些。"}},{"pos":"N-VAR 可变名词","cn":"（计算机、文字处理器等的）输出信息，输出文件","en":"The output of a computer or word processor is the information that it displays on a screen or prints on paper as a result of a particular program.","ex":{"en":"You run the software, you look at the output, you make modifications.","cn":"运行该软件，查看输出结果并进行修正。"}}]},"media":{"uk":"media/uk/output__gb_1.mp3","us":"media/us/output__us_1.mp3"},"examples":[{"en":"Computers can now output data much more quickly.","cn":"现在计算机能更快地输出数据。"},{"en":"Manufacturing output has increased by 8%.","cn":"工业产量增长了 8%。"}]},"outdated":{"oxford":{"phon":"ˌaʊtˈdeɪtɪd","pos":"adjective","senses":[{"en":"no longer useful because of being old-fashioned","cn":"过时的；陈旧的","ex":{"en":"outdated equipment","cn":"过时的设备"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"过时的；陈旧的；老式的；废弃的","en":"If you describe something as outdated, you mean that you think it is old-fashioned and no longer useful or relevant to modern life.","ex":{"en":"...outdated and inefficient factories","cn":"陈旧、低效的工厂"}}]},"media":{"uk":"media/uk/outdated__gb_1.mp3","us":"media/us/outdated__us_1.mp3"},"examples":[{"en":"These figures are now outdated.","cn":"这些数字现在已经过时。"},{"en":"outdated equipment","cn":"过时的设备"}]},"outpouring":{"oxford":{"phon":"ˈaʊtpɔːrɪŋ","pos":"noun","senses":[{"en":"a strong and sudden expression of feeling","cn":"（感情的）迸发，倾泻","g":"[usually plural]","ex":{"en":"spontaneous outpourings of praise","cn":"一片自然迸发的赞美声"}},{"en":"a large amount of something produced in a short time","cn":"涌现；喷涌","ex":{"en":"a remarkable outpouring of new ideas","cn":"新思想的大量涌现"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（感情、反应等的）迸发，爆发，倾泻","en":"An outpouring of something such as an emotion or a reaction is the expression of it in an uncontrolled way.","ex":{"en":"The news of his death produced an instant outpouring of grief.","cn":"他死亡的消息立即引发了强烈的悲痛。"}}]},"media":{"uk":"media/uk/outpouring__gb_1.mp3","us":"media/us/outpouring__us_1.mp3"},"examples":[{"en":"a remarkable outpouring of new ideas","cn":"新思想的大量涌现"},{"en":"spontaneous outpourings of praise","cn":"一片自然迸发的赞美声"}]},"outrageous":{"media":{"uk":"media/uk/outrageous__gb_1.mp3","us":"media/us/outrageous__us_1.mp3"},"oxford":{"phon":"aʊtˈreɪdʒəs","pos":"adjective","senses":[{"en":"offensive and unacceptable","cn":"令人发指的；骇人听闻的","ex":{"en":"outrageous behaviour","cn":"极端无礼的行为"}},{"en":"very unusual and intended to shock people slightly","cn":"怪诞的；怪异吓人的","ex":{"en":"She says the most outrageous things sometimes.","cn":"她有时候尽说些耸人听闻的事。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"令人无法容忍的；骇人的","en":"If you describe something as outrageous, you are emphasizing that it is unacceptable or very shocking.","ex":{"en":"I must apologise for my outrageous behaviour","cn":"我必须为自己极端无礼的行为道歉。"}}]},"examples":[{"en":"She says the most outrageous things sometimes.","cn":"她有时候尽说些耸人听闻的事。"},{"en":"They behaved outrageously.","cn":"他们的行为表现让人难以容忍。"}]},"outside":{"media":{"uk":"media/uk/outside__gb_1.mp3","us":"media/us/outside__us_1.mp3"},"oxford":{"phon":"ˌaʊtˈsaɪd","pos":"adverb","senses":[{"en":"not in a room, building or container but on or to the outside of it","cn":"在外面；向外面","ex":{"en":"I'm seeing a patient—please wait outside.","cn":"我正在给病人看病，请在外面等候。"}},{"en":"not inside a building","cn":"在户外；露天","ex":{"en":"It's warm enough to eat outside.","cn":"天气暖和了，可以露天吃饭了。"}},{"en":"on or to a place on the outside of something","cn":"在…外面；向…外面","ex":{"en":"You can park your car outside our house.","cn":"你可以把汽车停在我们家屋外。"},"pos":"preposition"},{"en":"away from or not in a particular place","cn":"离开；不在","ex":{"en":"It's the biggest theme park outside the United States.","cn":"这是美国以外最大的主题游乐园。"},"pos":"preposition"},{"en":"not part of something","cn":"不在…范围内；不属于","ex":{"en":"The matter is outside my area of responsibility.","cn":"此事不属于我的职责范围。"},"pos":"preposition"},{"en":"more than the amount of time mentioned","cn":"（时间）超出，多于","ex":{"en":"The winning time was just nine seconds outside the world record.","cn":"第一名所用的时间只比世界纪录多 9 秒。"},"pos":"preposition"},{"en":"apart from","cn":"除了","ex":{"en":"There was nothing they could do, outside of hoping things would get better.","cn":"除了盼望情况好转，他们无能为力。"},"pos":"preposition"},{"en":"the outer side or surface of something","cn":"外部；外表","g":"[countable, usually singular]","ex":{"en":"The outside of the house needs painting.","cn":"房子的外墙需要油漆一下。"},"pos":"noun"},{"en":"the area that is near or around a building, etc.","cn":"（建筑物等的）周围，外围","g":"[singular]","ex":{"en":"I walked around the outside of the building.","cn":"我绕着这座建筑四周散步。"},"pos":"noun"},{"en":"the part of a road nearest to the middle","cn":"（靠近路中央的）外侧，外手","g":"[singular]","ex":{"en":"Always overtake on the outside.","cn":"超车务必走外侧道。"},"pos":"noun"},{"en":"the part of a curving road or track furthest from the inner or shorter side of the curve","cn":"（弯曲路面或轨道的）外道，外缘","g":"[singular]","pos":"noun"},{"en":"of, on or facing the outer side","cn":"外部的；在外面的；向外的","ex":{"en":"The outside walls are damp.","cn":"外墙潮湿。"},"pos":"adjective"},{"en":"not located in the main building; going out of the main building","cn":"主建筑物以外的；向外面的","ex":{"en":"an outside toilet","cn":"户外厕所"},"pos":"adjective"},{"en":"not included in or connected with your group, organization, country, etc.","cn":"不属于本团体（或机构、国家等）的；外部的；不相关的","ex":{"en":"We plan to use an outside firm of consultants.","cn":"我们计划利用外面的咨询公司。"},"pos":"adjective"},{"en":"used to say that something is very unlikely","cn":"不可能的；可能性极小的","ex":{"en":"They have only an outside chance of winning.","cn":"他们的胜算极小。"},"pos":"adjective"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"外面；外部；外表","en":"The outside of something is the part which surrounds or encloses the rest of it.","ex":{"en":"...the outside of the building","cn":"建筑物的外部"}},{"pos":"ADV 副词","cn":"在外面；在室外；在建筑物近旁","en":"If you are outside, you are not inside a building but are quite close to it.","ex":{"en":"'Was the car inside the garage?' — 'No, it was still outside.'","cn":"“车在车库里吗？”——“不，还在外面。”"}},{"pos":"PREP 介词","cn":"在（房间）的外面","en":"If you are outside a room, you are not in it but are in the passage or area next to it.","ex":{"en":"She'd sent him outside the classroom","cn":"她让他到教室外面去。"}},{"pos":"ADJ 形容词","cn":"外部（世界）的；外界的","en":"When you talk about the outside world, you are referring to things that happen or exist in places other than your own home or community.","ex":{"en":"...a side of Morris's character she hid carefully from the outside world","cn":"莫里斯小心隐藏不让外人知晓的性格中的一面"}},{"pos":"PREP 介词","cn":"不在…；在（某地）之外","en":"People or things outside a country, town, or region are not in it.","ex":{"en":"...an old castle outside Budapest","cn":"布达佩斯城外的古堡"}},{"pos":"ADJ 形容词","cn":"（车道）靠近路中间的，快车道的","en":"On a road with two separate carriageways, the outside lanes are the ones which are closest to its centre.","ex":{"en":"It was travelling in the outside lane at 78mph.","cn":"它正以78英里的时速在快车道上疾驶。"}},{"pos":"ADJ 形容词","cn":"（人员、机构等）外部的","en":"Outside people or organizations are not part of a particular organization or group.","ex":{"en":"The company now makes much greater use of outside consultants.","cn":"该公司现在对外聘顾问的利用更加充分。"}},{"pos":"PREP 介词","cn":"在（…领域）以外","en":"Outside a particular institution or field of activity means in other fields of activity or in general life.","ex":{"en":"The condition is practically unknown outside psychiatry clinics.","cn":"除了医院的精神病科外，这种病几乎不为人知。"}},{"pos":"PREP 介词","cn":"在…范围以外","en":"Something that is outside a particular range of things is not included within it.","ex":{"en":"She is a beautiful boat, but way, way outside my price range","cn":"这条船很漂亮，但价格却远远超出我能承受的范围。"}},{"pos":"PREP 介词","cn":"在（某段时间）以外","en":"Something that happens outside a particular period of time happens at a different time from the one mentioned.","ex":{"en":"They are open outside normal daily banking hours.","cn":"它们在银行正常营业时间以外开放。"}},{"pos":"PREP-PHRASE 短语介词","cn":"除了…之外；不包括","en":"Outside of is used to introduce the only thing or person that prevents your main statement from being completely true.","ex":{"en":"Every single relationship I've had with a man, outside of my husband, has ended in disaster.","cn":"除了我丈夫之外，我与所有男人的感情都以悲剧收场。"}},{"pos":"PHRASE 短语","cn":"最多；充其量；最晚","en":"You use at the outside to say that you think that a particular amount is the largest possible in a particular situation, or that a particular time is the latest possible time for something to happen.","ex":{"en":"Give yourself forty minutes at the outside.","cn":"最多给自己留40分钟。"}}]},"examples":[{"en":"I didn't go into the temple — I only saw it from the outside.","cn":"我没有走进庙宇，只是从外面看了一下。"},{"en":"We live in a small village just outside Leeds.","cn":"我们就住在利兹市外的一个小村子里。"}]},"outs":{"lemma":"out","media":{"uk":"media/uk/out__gb_1.mp3","us":"media/us/out__us_1.mp3"}},"outperformed":{"oxford":{"phon":"ˌaʊtpəˈfɔːm","pos":"verb","senses":[{"en":"to achieve better results than sb/sth （","cn":"效益上）超过，胜过"}]}},"outhouses":{"oxford":{"phon":"ˈaʊthaʊs","pos":"noun","senses":[{"en":"( BrE ) a small building, such as a shed , outside a main building （","cn":"主建筑的）外围建筑，附属建筑"},{"en":"( especially NAmE ) a toilet in a small building of its own","cn":"屋外厕所"}]}},"outpaced":{"oxford":{"phon":"ˌaʊtˈpeɪs","pos":"verb","senses":[{"en":"to go, rise, improve, etc. faster than sb/sth （","cn":"在速度上）超过；比 … 快"}]}},"outfitters":{"lemma":"outfitter"},"ought":{"collins":{"senses":[{"pos":"PHR-MODAL 情态动词短语","cn":"（认为某事道义上正确，尤用于提出或征求建议或意见）应当，应该","en":"You use ought to to mean that it is morally right to do a particular thing or that it is morally right for a particular situation to exist, especially when giving or asking for advice or opinions.","ex":{"en":"Mark, you've got a good wife. You ought to take care of her","cn":"马克，你娶了个好妻子，应该好好待她。"}},{"pos":"PHR-MODAL 情态动词短语","cn":"（认为某事可行或重要，尤用于提出或征求建议或意见）应当，应该","en":"You use ought to when saying that you think it is a good idea and important for you or someone else to do a particular thing, especially when giving or asking for advice or opinions.","ex":{"en":"You don't have to be alone with him and I don't think you ought to be","cn":"你不必单独跟他呆在一起，而且我认为你也不该这样。"}},{"pos":"PHR-MODAL 情态动词短语","cn":"（认为某事确实，或预计某事发生或已经发生）应该/应该已经","en":"You use ought to to indicate that you expect something to be true or to happen. You use ought to have to indicate that you expect something to have happened already.","ex":{"en":"'This ought to be fun,' he told Alex, eyes gleaming.","cn":"“这应该会很有趣！”他对亚历克斯说，两眼闪闪发光。"}},{"pos":"PHR-MODAL 情态动词短语","cn":"（表示某事本应如此，但实际情况未必）应该","en":"You use ought to to indicate that you think that something should be the case, but might not be.","ex":{"en":"By rights the Social Democrats ought to be the favourites in the election. But nothing looks less certain","cn":"社会民主党按理应该最有希望赢得这次选举，但一切从未如此不确定过。"}},{"pos":"PHR-MODAL 情态动词短语","cn":"（表示从已知情况推测某事已经发生，但不确定）应该","en":"You use ought to to indicate that you think that something has happened because of what you know about the situation, but you are not certain.","ex":{"en":"He ought to have reached the house some time ago.","cn":"他应该早就到房子那儿了。"}},{"pos":"PHR-MODAL 情态动词短语","cn":"（与过去分词连用，表示预期的事未发生或预计的情况并非如此）本该，本当","en":"You use ought to have with a past participle to indicate that something was expected to happen or be the case, but it did not happen or was not the case.","ex":{"en":"Basically the system ought to have worked","cn":"其实这套系统本应发挥作用的。"}},{"pos":"PHR-MODAL 情态动词短语","cn":"（与过去分词连用，表示未做本应该做的事情）本该，本当","en":"You use ought to have with a past participle to indicate that although it was best or correct for someone to do something in the past, they did not actually do it.","ex":{"en":"I realize I ought to have told you about it","cn":"我意识到自己本该把这件事告诉你的。"}},{"pos":"PHR-MODAL 情态动词短语","cn":"（礼貌地告知某人自己必须做某事）该，得","en":"You use ought to when politely telling someone that you must do something, for example that you must leave.","ex":{"en":"I really ought to be getting back now","cn":"现在我真得回去了。"}}]}},"outcomes":{"lemma":"outcome"},"outsized":{"oxford":{"phon":"ˈaʊtsaɪz","pos":"adj.","senses":[{"en":"larger than the usual size","cn":"较大的；超过一般型号的"},{"en":"designed for large people","cn":"特体的；特大号的"}]}},"outnumbered":{"lemma":"outnumber"},"outlet":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"经销店；专营店","en":"An outlet is a shop or organization which sells the goods made by a particular manufacturer.","ex":{"en":"...the largest retail outlet in the city.","cn":"该市最大的零售商店"}},{"pos":"N-COUNT 可数名词","cn":"廉价商品经销店；折扣店","en":"An outlet or an outlet store is a place which sells slightly damaged or outdated goods from a particular manufacturer, or goods that it made in greater quantities than needed.","ex":{"en":"...the factory outlet store in Belmont.","cn":"位于贝尔蒙特的厂家直销型折扣店"}},{"pos":"N-COUNT 可数名词","cn":"（情感的）发泄途径；（思想的）表达方式","en":"If someone has an outlet for their feelings or ideas, they have a means of expressing and releasing them.","ex":{"en":"Her father had found an outlet for his ambition in his work.","cn":"她父亲在工作中找到了施展抱负的机会。"}},{"pos":"N-COUNT 可数名词","cn":"出口；排放管","en":"An outlet is a hole or pipe through which liquid or air can flow away.","ex":{"en":"...a warm air outlet.","cn":"热气出口"}},{"pos":"N-COUNT 可数名词","cn":"（通常指墙上的）电源插座","en":"An outlet is a place, usually in a wall, where you can connect electrical devices to the electricity supply."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a building or place where things are sold","cn":""},{"en":"a small shop that sells fashionable clothes or other objects","cn":""},{"en":"a very large shop, especially one that is built outside the centre of a city","cn":""}]},"collocations":{"phrases":["ADJ. specialist | high-street, local | commercial, distribution, retail, sales | DIY, fast-food, etc.","PREP. ~ for a retail outlet for exotic plants 2 means of releasing energy/strong feeling/talents","ADJ. emotional | creative","VERB + OUTLET have | find | provide (sb with) Sport provided an outlet for his energy. | need","PREP. ~ for She needs an outlet for her talents. 3 pipe/hole","ADJ. electrical, gas, sewage, socket, waste, water","OUTLET + NOUN hose, pipe"]},"media":{"uk":"media/ldoce/hwd/bre/c/outlet0205.mp3","us":"media/ldoce/hwd/ame/4/outlet.mp3"},"examples":[{"en":"She needed to find an outlet for her many talents and interests.","cn":"她多才多艺、兴趣广泛，需要找个施展的机会。"},{"en":"The business has 34 retail outlets in this state alone.","cn":"那家商号仅在本州就有 34 个零售店。"}],"oxford":{"phon":"ˈaʊtlet","pos":"noun","senses":[{"en":"a shop or an organization that sells goods made by a particular company or of a particular type","cn":"专营店；经销店","ex":{"en":"The business has 34 retail outlets in this state alone.","cn":"那家商号仅在本州就有 34 个零售店。"}},{"en":"a shop that sells goods of a particular make at reduced prices","cn":"（某品牌的）折扣店","ex":{"en":"the Nike outlet in the outlet mall","cn":"折扣品商场里的耐克折扣店"}},{"en":"a way of expressing or making good use of strong feelings, ideas or energy","cn":"（感情、思想、精力发泄的）出路；表现机会","ex":{"en":"She needed to find an outlet for her many talents and interests.","cn":"她多才多艺、兴趣广泛，需要找个施展的机会。"}},{"en":"a pipe or hole through which liquid or gas can flow out","cn":"出口；排放管","ex":{"en":"a sewage outlet","cn":"污水排放口"}},{"en":"a device in a wall that you put a plug (= a small plastic object with two or three metal pins) into in order to connect electrical equipment to the power supply of a building","cn":"（电源）插座","lab":"both North American English","ex":{"en":"The appliance can be connected to any standard outlet.","cn":"这件电器可以连接到任一标准电源插口。"}}]}},"outsider":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（某个团体或组织）外部的人","en":"An outsider is someone who does not belong to a particular group or organization.","ex":{"en":"The most likely outcome may be to subcontract much of the work to an outsider.","cn":"最可能的结果是将大量的工作分包出去。"}},{"pos":"N-COUNT 可数名词","cn":"（不为某一团体所接受或感觉不属其中的）外人","en":"An outsider is someone who is not accepted by a particular group, or who feels that they do not belong in it.","ex":{"en":"Malone, a cop, felt as much an outsider as any of them.","cn":"马隆是个警察，他跟他们一样都觉得自己像个外人。"}},{"pos":"N-COUNT 可数名词","cn":"（在竞赛中）不大可能获胜的人（或队伍）","en":"In a competition, an outsider is a competitor who is unlikely to win.","ex":{"en":"He was an outsider in the race to be the new UN Secretary-General.","cn":"在新一任联合国秘书长的角逐中，他的胜算很小。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"to be in a position where you are likely to lose a game, competition, election or war because you are not doing as well as your opponent","cn":""},{"en":"to be losing a game, competition, or election","cn":""},{"en":"to be losing a game or competition, or election - used especially in news reports","cn":""}]},"collocations":{"phrases":["ADJ. complete | political, social","VERB + OUTSIDER feel I felt a complete outsider.","PREP. ~ to an outsider to the group 2 competitor who will probably not win","ADJ. complete, rank","PREP. ~ in The firm has gone from being an outsider in the market to being a market leader."]},"media":{"uk":"media/ldoce/hwd/bre/0/outsider0205.mp3","us":"media/ldoce/hwd/ame/c/outsider.mp3"},"examples":[{"en":"To everyone's surprise, the post went to a rank outsider (= a complete outsider ).","cn":"出人意料的是，那个职位竟然落到一个毫不起眼的人头上。"},{"en":"The race was won by a 20–1 outsider.","cn":"比赛获胜者是个不被看好、20 赔 1 的赛马。"}],"oxford":{"phon":"ˌaʊtˈsaɪdə(r)","pos":"noun","senses":[{"en":"a person who is not accepted as a member of a society, group, etc.","cn":"外人；局外人","ex":{"en":"Here she felt she would always be an outsider.","cn":"她在这里总觉得是个外人。"}},{"en":"a person who is not part of a particular organization or profession","cn":"（组织、行业）外部的人；外来者","ex":{"en":"They have decided to hire outsiders for some of the key positions.","cn":"他们决定在某些关键职位上聘任外来人员。"}},{"en":"a person or an animal taking part in a race or competition that is not expected to win","cn":"（比赛中）不被看好的人（或动物）","ex":{"en":"The race was won by a rank outsider (= a complete outsider).","cn":"跑步比赛由一名大冷门选手获胜。"}}]}},"outrage":{"collins":{"senses":[{"pos":"VERB 动词","cn":"使震怒;激怒","en":"If you are outraged by something, it makes you extremely shocked and angry.","ex":{"en":"Many people have been outraged by some of the things that have been said","cn":"其中的一些言论激怒了很多人。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"愤慨；义愤","en":"Outrage is an intense feeling of anger and shock.","ex":{"en":"The decision provoked outrage from women and human rights groups","cn":"这一决定激起了妇女和人权组织的强烈愤慨。"}},{"pos":"N-COUNT 可数名词","cn":"暴行；骇人听闻的事件","en":"You can refer to an act or event which you find very shocking as an outrage .","ex":{"en":"The latest outrage was to have been a co-ordinated gun and bomb attack on the station","cn":"最近的一起暴行是同时动用了枪支和炸弹的对车站的袭击。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a very strong feeling of anger","cn":""},{"en":"a very strong feeling of anger that is difficult to control or is expressed very suddenly or violently","cn":""},{"en":"extreme anger and shock because you think something is unfair or wrong","cn":""}]},"vocab":{"pos":"n v","senses":[{"en":"If you consider how people are treated in airports an outrage , you get really angry over airport security or the price of airport food. Six dollars for a piece of pizza? What an outrage !"}]},"collocations":{"phrases":["ADJ. genuine | widespread | international | public | moral Media reports generated moral outrage.","VERB + OUTRAGE be greeted with, cause, generate, provoke, spark The news was greeted with outrage. | feel | express, voice Shopkeepers voice","OUTRAGE + VERB be directed at sb/sth Much of the outrage was directed at foreign nationals.","PREP. in ~ The guests all shouted in outrage. | with ~ She was trembling with outrage. | ~ at Campaigners have expressed outrage at the deci","PHRASES cries/howls of outrage The announcement provoked howls of outrage. | a feeling/sense of outrage 2 cruel/shocking act","VERB + OUTRAGE commit, perpetrate the outrages committed by the invading army","PREP. ~ against The new law on pensions is an outrage against the elderly."]},"media":{"uk":"media/ldoce/hwd/bre/e/outrage_v0205.mp3","us":"media/ldoce/hwd/ame/f/outrage1.mp3"},"examples":[{"en":"No one has yet claimed responsibility for this latest bomb outrage.","cn":"迄今还没有人宣称对最近的爆炸暴行负责。"},{"en":"Environmentalists have expressed outrage at the ruling.","cn":"环境保护主义者对这一裁决表示愤慨。"}],"oxford":{"phon":"ˈaʊtreɪdʒ","pos":"noun","senses":[{"en":"a strong feeling of shock and anger","cn":"愤怒；义愤；愤慨","g":"[uncountable]","ex":{"en":"The judge's remarks caused public outrage.","cn":"裁判的话引起了公愤。"}},{"en":"an act or event that is violent, cruel or very wrong and that shocks people or makes them very angry","cn":"暴行；骇人听闻的事","g":"[countable]","ex":{"en":"No one has yet claimed responsibility for this latest terrorist outrage.","cn":"迄今还没有人宣称对最近的恐怖主义暴行负责。"}},{"en":"to make somebody very shocked and angry","cn":"使震怒；激怒","ex":{"en":"He was outraged at the way he had been treated.","cn":"他对所遭受的待遇感到非常愤怒。"},"pos":"verb"},{"en":"a former British organization that worked for the rights of LGBT people. OutRage! started in 1990 and became well known for its use of direct action which it often combined with humour, as in the ‘Queer St Valentine's Day Carnival’. One of OutRage's best-known campaigners was the author and political activist Peter Tatchell. OutRage! closed down in 2011.","cn":"曾为英国同性恋，双性恋和变性者权利工作的前英国组织。暴行！成立于1990年，以“直接行动”（通常与幽默相结合）而闻名，例如“ Queer St Valentine's Day Carnival”。作者和政治活动家彼得·塔切尔（Peter Tatchell）是OutRage最著名的活动家之一。暴行！在2011年关闭。","pos":""}]}},"outskirts":{"collins":{"senses":[{"pos":"N-PLURAL 复数名词","cn":"市郊；郊区","en":"The outskirts of a city or town are the parts of it that are farthest away from its centre.","ex":{"en":"Hours later we reached the outskirts of New York.","cn":"我们几小时后到达了纽约市郊。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the part of something that is furthest from its centre or nearest the place where it ends","cn":""},{"en":"the part of something that is near its left or right edge","cn":""},{"en":"the edge of something circular, especially the top of a cup or glass, or the outside edge of a pair of glasses","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"Some people like to live downtown. Others prefer the open spaces of the suburbs. But if you live in between the two, you are in the outskirts , the place where the city ends and the suburbs begin."}]},"collocations":{"phrases":["ADJ. sprawling | city | northern, etc.","VERB + OUTSKIRTS reach","PREP. in the ~ a school in the outskirts of Athens | on the ~ We live on the outskirts of Leeds. | through the ~ driving through the outskir"]},"media":{"uk":"media/ldoce/hwd/bre/1/outskirts0205.mp3","us":"media/ldoce/hwd/ame/e/outskirts.mp3"},"examples":[{"en":"They live on the outskirts of Milan.","cn":"他们住在米兰市郊。"},{"en":"They live on the outskirts of Paris.","cn":"他们住在巴黎的郊区。"}],"oxford":{"phon":"ˈaʊtskɜːts","pos":"noun","senses":[{"en":"the parts of a town or city that are furthest from the centre","cn":"（市镇的）边缘地带；市郊","ex":{"en":"They live on the outskirts of Milan.","cn":"他们住在米兰市郊。"}}]}},"outnumber":{"collins":{"senses":[{"pos":"VERB 动词","cn":"（在数量上）压倒，比…多","en":"If one group of people or things outnumbers another, the first group has more people or things in it than the second group.","ex":{"en":"...a town where men outnumber women four to one","cn":"男性比女性多3倍的城镇"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to be more than a number or amount, especially a fixed number or limit - used especially in official reports or documents","cn":""},{"en":"if one type of person or thing outnumbers another, there are more of the first type than of the second","cn":""},{"en":"if profits, sales, income etc are up they are larger than at a time in the past","cn":""}]},"collocations":{"phrases":["ADV. considerably, easily, far, greatly, heavily, substantially, vastly Their failures vastly outnumber their successes. | almost | slightly","PREP. by The Czechs outnumbered the Slovaks by at least two to one.","PHRASES be hopelessly outnumbered The Spanish were hopelessly outnumbered in the battle."]},"media":{"uk":"media/ldoce/hwd/bre/4/outnumber0205.mp3","us":"media/ldoce/hwd/ame/6/outnumber.mp3"},"examples":[{"en":"In this profession, women outnumber men by two to one (= there are twice as many women as men).","cn":"在这个行业，女性人数是男性的两倍。"},{"en":"The demonstrators were heavily outnumbered by the police.","cn":"示威者人数远不及警察人数。"}],"oxford":{"phon":"ˌaʊtˈnʌmbə(r)","pos":"verb","senses":[{"en":"to be greater in number than somebody/something","cn":"（在数量上）压倒，比…多","ex":{"en":"The demonstrators were heavily outnumbered by the police.","cn":"示威者人数远不及警察人数。"}}]}},"outcast":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"被排斥者；被抛弃者","en":"An outcast is someone who is not accepted by a group of people or by society.","ex":{"en":"He had always been an outcast, unwanted and alone","cn":"他一直都被视为异类，无人理睬，形单影只。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone who is not accepted by the people they live among, or who has been forced out of their home","cn":"被〔家庭﹑社会等〕遗弃[排斥]的人﹔被逐出者"}]},"vocab":{"pos":"n adj","senses":[{"en":"An outcast is someone who isn't wanted. To remember what outcast means, flip it around: outcasts have been cast out from somewhere."}]},"collocations":{"phrases":["ADJ. social He was treated as a social outcast.","VERB + OUTCAST make sb Her criminal past made her an outcast. | treat sb as/like","PREP. ~ from an outcast from society"]},"media":{"uk":"media/ldoce/hwd/bre/c/outcast0205.mp3","us":"media/ldoce/hwd/ame/1/outcast.mp3"},"examples":[{"en":"People with the disease were often treated as social outcasts.","cn":"患有这种疾病的人常被社会摈弃。"},{"en":"Smokers often feel as though they are being treated as social outcasts.","cn":"吸烟者常常觉得自己遭到社会排斥。"}],"oxford":{"phon":"ˈaʊtkɑːst","pos":"adjective","senses":[{"en":"not accepted by society or by a particular group","cn":"被抛弃的，被逐出的","ex":{"en":"He had been made to feel socially outcast.","cn":"他被迫感到自己被社会排斥。"}},{"en":"a person who is not accepted by society or by a particular group","cn":"边缘人，被抛弃者（被社会或特定群体排斥的人）","ex":{"en":"People with the disease were often treated as social outcasts.","cn":"患有这种疾病的人常被社会摈弃。"},"pos":"noun"}]}},"outlay":{"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"（必要的）费用，开支","en":"Outlay is the amount of money that you have to spend in order to buy something or start a project.","ex":{"en":"Apart from the capital outlay of buying the machine, dishwashers can actually save you money","cn":"除了购置所用开支，洗碗机实际上能为你省钱。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the amount of money that is spent, especially by a government or other organization","cn":""},{"en":"the amount of money that a government, organization, or person spends during a particular period of time – used especially in official documents or reports","cn":""},{"en":"the money that a person or organization has to spend on heating, rent, wages etc","cn":""}]},"collocations":{"phrases":["ADJ. considerable, huge, large, massive | modest, small | initial The revenue from the farm could repay the initial outlay within three year","VERB + OUTLAY make | require The project would require little financial outlay. | recoup, recover | repay","PREP. ~ on The railway had made a considerable capital outlay on new rolling stock."]},"media":{"uk":"media/ldoce/hwd/bre/7/brelasdeoutlay.mp3","us":"media/ldoce/hwd/ame/d/outlay.mp3"},"examples":[{"en":"The business quickly repaid the initial outlay on advertising.","cn":"这家公司很快偿付了初期的广告费。"},{"en":"a massive financial/capital outlay","cn":"大量的财政/资本开支"}],"oxford":{"phon":"ˈaʊtleɪ","pos":"noun","senses":[{"en":"the money that you have to spend in order to start a new project","cn":"（启动新项目的）开支，费用","ex":{"en":"The business quickly repaid the initial outlay on advertising.","cn":"这家公司很快偿付了初期的广告费。"}}]}},"outbreak":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（暴力活动、疾病等的）爆发，突然发生","en":"If there is an outbreak of something unpleasant, such as violence or a disease, it suddenly starts to happen.","ex":{"en":"The four-day festival ended a day early after an outbreak of violence involving hundreds of youths.","cn":"一场有数百名年轻人卷入的暴力活动发生后，为期4天的节庆活动被迫提前一天结束。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"when a lot of people suddenly start to get an illness at the same time","cn":""},{"en":"when a lot of people in an area or country get a disease, and it spreads very quickly","cn":""},{"en":"to start happening - use this about unpleasant things like fires, wars, or diseases","cn":""}]},"collocations":{"phrases":["ADJ. large, major, serious | fresh, further, new | occasional, periodic, sporadic | recurrent, repeated | sudden | cholera, salmonella, etc.","VERB + OUTBREAK lead to the events that led to the outbreak of World War I","OUTBREAK + VERB occur","PREP. ~ of A new outbreak of smallpox occurred in 1928.","PHRASES an outbreak of disease, an outbreak of rain, an outbreak of war/fighting/hostilities/violence"]},"media":{"uk":"media/ldoce/hwd/bre/0/outbreak0205.mp3","us":"media/ldoce/hwd/ame/e/outbreak.mp3"},"examples":[{"en":"Outbreaks of rain are expected in the afternoon.","cn":"下午将有暴雨。"},{"en":"the outbreak of war","cn":"战争的爆发"}],"oxford":{"phon":"ˈaʊtbreɪk","pos":"noun","senses":[{"en":"the sudden start of something unpleasant, especially violence or a disease","cn":"（暴力、疾病等坏事的）爆发，突然发生","lab":"British English","ex":{"en":"the outbreak of war","cn":"战争的爆发"}}]}},"outing":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（通常指集体）远足，短途旅行","en":"An outing is a short enjoyable trip, usually with a group of people, away from your home, school, or place of work.","ex":{"en":"One evening, she made a rare outing to the local discotheque.","cn":"她有天晚上破天荒地去了一次当地的迪斯科舞厅。"}},{"pos":"N-COUNT 可数名词","cn":"体育比赛","en":"In sport, an outing is an occasion when a player competes in a particular contest or competition.","ex":{"en":"Playing against Zebre in England's first outing, he suffered a whiplash injury to his neck.","cn":"在英格兰队首次对阵热布里的比赛中，他颈部受了挥鞭伤。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"to visit a beach, an area of countryside, a town etc for pleasure and come back home on the same day","cn":""},{"en":"a visit to a beach, an area of countryside, a town etc when you go there and come back the same day","cn":""},{"en":"a journey that someone makes each day to work, especially when they live a fairly long way away from their work","cn":""}]},"collocations":{"phrases":["ADJ. little | special | day's, summer, weekend | annual | family, school, social","VERB + OUTING be/go on","PREP. ~ from The children were on a day's outing from school. | ~ to a family outing to the seaside"]},"media":{"uk":"media/ldoce/hwd/bre/5/outing0205.mp3","us":"media/ldoce/hwd/ame/f/outing.mp3"},"examples":[{"en":"We went on an outing to London.","cn":"我们游览了伦敦。"},{"en":"a family outing","cn":"全家远足"}],"oxford":{"phon":"ˈaʊtɪŋ","pos":"noun","senses":[{"en":"a trip that you go on for pleasure or education, usually with a group of people and lasting no more than one day","cn":"（集体）出外游玩（或学习等）；远足","g":"[countable]","lab":"British English","ex":{"en":"a family outing","cn":"全家远足"}},{"en":"an occasion when somebody takes part in a competition","cn":"参赛；比赛","g":"[countable]","lab":"sport, informal，，"},{"en":"the practice of naming people as gay or lesbian in public, when they would prefer to keep this information private","cn":"（违背同性恋者本人意愿）对（其）身份的公开挑明","g":"[uncountable, countable]"}]},"base":"out"},"outburst":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（尤指愤怒等感情的）爆发，迸发","en":"An outburst of an emotion, especially anger, is a sudden strong expression of that emotion.","ex":{"en":"...an outburst of anger.","cn":"勃然大怒"}},{"pos":"N-COUNT 可数名词","cn":"（暴力活动的）突发","en":"An outburst of violent activity is a sudden period of this activity.","ex":{"en":"Five people were reported killed today in a fresh outburst of violence.","cn":"据报道在今天最新发生的暴乱中有5人丧生。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"if someone, especially a child, has or throws a tantrum , they shout angrily and cry, especially because they cannot have what they want","cn":""},{"en":"to start a loud angry argument with someone, especially in a public place and in a way that is embarrassing","cn":""},{"en":"a sudden expression of very strong angry feelings, especially because you cannot control your anger any longer","cn":""}]},"collocations":{"phrases":["ADJ. sudden | spontaneous | occasional her occasional outbursts of temper | angry, furious, violent | emotional, hysterical, passionate","PREP. ~ against A player was cautioned for his angry outburst against the referee. | ~ of an outburst of anger/laughter/temper/violence"]},"media":{"uk":"media/ldoce/hwd/bre/d/outburst0205.mp3","us":"media/ldoce/hwd/ame/f/outburst.mp3"},"examples":[{"en":"She was alarmed by his violent outburst.","cn":"他暴跳如雷，令她惊恐万状。"},{"en":"an outburst of racism","cn":"种族主义的突然高涨"}],"oxford":{"phon":"ˈaʊtbɜːst","pos":"noun","senses":[{"en":"a sudden strong expression of an emotion","cn":"（感情的）爆发，迸发","ex":{"en":"an outburst of anger","cn":"突然大怒"}},{"en":"a sudden increase in a particular activity or attitude","cn":"（活动的）激增；（态度的）激化","ex":{"en":"an outburst of racism","cn":"种族主义的突然高涨"}}]}}});
